\title{Good Primes in Bad Places:\\
Denominators of Multiples of Integral Points on Mordell Curves}
\author{Aristotle}
\date{August 15, 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $N$ be a nonzero integer and let $E_N : y^2 = x^3 + N$ be the Mordell curve, with discriminant
$\Delta = -432N^2$, so that the primes of bad reduction lie in $\{2,3\}\cup\{\ell : \ell \mid N\}$.
A folklore expectation --- attractive because it would turn the arithmetic of $E_N$ into a factoring
oracle for $N$ --- asserts that for an integral point $P$ of $E_N$ the denominator of the
$x$-coordinate of $nP$ is divisible only by primes of bad reduction; for $N = pq$ a semiprime this
would mean only $2,3,p,q$ can occur. We call this the \emph{``only bad primes'' conjecture} and prove
that it is false at every level of the multiplication tower. The smallest counterexample is
$N = 55 = 5\cdot 11$, $P = (9,28)$, where $x(2P) = 2601/3136$ with $3136 = 2^6\cdot 7^2$ and $7$ a
prime of good reduction. We then explain the phenomenon completely: for an integral point $(x,y)$ with
$y \neq 0$ and a prime $\ell \nmid 6N$ one has $\ell \mid \den x(2P) \iff \ell \mid y \iff 2\bar P = O$
in $E_N(\FF_\ell)$, and sharply $v_\ell(\den x(2P)) = 2 v_\ell(y)$; at $n=3$ the same holds with the
third division polynomial $\psi_3 = 3x^4+12Nx$ and $3$-torsion. Thus the primes appearing in
denominators are the primes at which the \emph{point} reduces into torsion, a condition unrelated to
the discriminant. We prove that every prime $\ell \geq 5$ occurs as an extraneous good-reduction prime
for a suitable $N$, that arbitrarily many can occur in a single denominator, and that infinitely many
$N$ admit a failure. Along the doubling tower we prove a sharp dichotomy: at odd good primes the
denominator exponent is frozen, while at the prime $2$ it grows by exactly $2$ per doubling. Finally
we replace the false conjecture with a true one: $\den x(2P) \mid 4y^2$, so every prime dividing
$\den x(2P)$ divides $2y$. A consequence for the ``elliptic curves as factoring oracles'' heuristic is
that these denominators carry no signal about the factorisation of $N$.
\end{abstract}

\noindent\textbf{Keywords:} Mordell curve, elliptic curve, division polynomial, denominator, good
reduction, elliptic divisibility sequence, torsion, integral point.

\section{Introduction}

\subsection{The lure of the discriminant}

Write $r \in \QQ$ in lowest terms as $a/b$ with $b>0$ and $\gcd(a,b)=1$, and call $b = \den(r)$ its
denominator. If $P$ is a rational point on an elliptic curve over $\QQ$ in Weierstrass form, the
denominators of $x(nP)$ grow rapidly with $n$ and their prime factorisations encode a great deal of
arithmetic: the ``denominator square roots'' form the classical elliptic divisibility sequence, and
divisibility properties of such sequences underlie Lenstra's elliptic curve factorisation method.

That connection is seductive. It is tempting to believe the denominators themselves \emph{see} the
factorisation of $N$ for the Mordell curve
\[
  E_N : y^2 = x^3 + N,
\]
whose discriminant is $\Delta = -432N^2$ and whose bad primes therefore lie in
$\{2,3\}\cup\{\ell:\ell \mid N\}$. For $N=pq$ this would say only $2,3,p,q$ can occur in a
denominator --- so that one doubling of an integral point would reveal the factorisation.

\subsection{The conjecture and its refutation}

\begin{conjecture}[``only bad primes'']\label{conj:main}
Let $p,q$ be primes, $N=pq$, and let $(x,y)\in\ZZ^2$ satisfy $y^2 = x^3+N$. Then every prime dividing
$\den\big(x(nP)\big)$ lies in $\{2,3,p,q\}$.
\end{conjecture}

\begin{theorem}[Refutation at $n=2$]\label{thm:A}
Conjecture \ref{conj:main} is false. For $N = 55 = 5\cdot 11$ and $P=(9,28)\in E_{55}(\QQ)$,
\[
  x(2P) = \frac{9^4 - 8\cdot 55\cdot 9}{4(9^3+55)} = \frac{2601}{3136},
  \qquad 3136 = 2^6\cdot 7^2,
\]
and $7 \nmid \Delta = -432\cdot 55^2$, i.e. $7$ is a prime of good reduction outside $\{2,3,5,11\}$.
\end{theorem}

A second, structurally motivated counterexample uses the identity $25m^2-1 = (5m-1)(5m+1)$: for
$m=6$, $N = 899 = 29\cdot 31$ and $P=(1,30)$ give $x(2P) = -799/400$ with $400 = 2^4\cdot 5^2$, and
$5 \notin\{2,3,29,31\}$ is again a good prime.

\subsection{What actually controls the denominators}

\begin{theorem}[Mechanism theorem]\label{thm:B}
Let $(x,y)\in\ZZ^2$ satisfy $y^2=x^3+N$ with $y \neq 0$, and let $\ell$ be a prime with
$\ell \nmid 6N$ (equivalently $\ell \nmid \Delta$). Then
$\ell \mid \den\big(x(2P)\big) \iff \ell \mid y$.
\end{theorem}

\begin{theorem}[Reduction/torsion bridge]\label{thm:C}
Under the hypotheses of Theorem \ref{thm:B}, with $\bar P$ the reduction of $P$ in $E_N(\FF_\ell)$,
\[
  \ell \mid \den\big(x(2P)\big) \iff \bar P + \bar P = O \ \text{ in } E_N(\FF_\ell).
\]
\end{theorem}

So a prime enters the denominator precisely when doubling pushes the reduced point into the kernel of
reduction. Nothing in that condition mentions the discriminant.

\subsection{Universality, and the repaired statement}

\begin{theorem}[No prime is excluded]\label{thm:D}
Let $\ell\ge 5$ be prime, $m \ge 1$, $N = \ell^2m^2-1$ and $P = (1,\ell m)$. Then $\ell \nmid 6N$
and $\ell \mid \den x(2P)$.
\end{theorem}

\begin{theorem}[Arbitrarily many extraneous primes]\label{thm:E}
Let $S$ be a finite set of primes $\ge 5$, $K = \prod_{\ell\in S}\ell$, $m \ge 1$, $N = K^2m^2-1$,
$P=(1,Km)$. Then every $\ell \in S$ is a good prime of $E_N$ dividing $\den x(2P)$.
\end{theorem}

\begin{theorem}[Infinitely many failures]\label{thm:F}
The set of $N$ for which some integral point of $E_N$ has a good-reduction prime in the denominator
of the $x$-coordinate of its double is infinite; $N = 25m^2-1$ with $P=(1,5m)$, $\ell = 5$, suffices.
\end{theorem}

\begin{theorem}[Repaired conjecture]\label{thm:G}
For any $(x,y)\in\ZZ^2$ with $y^2 = x^3+N$: $\den\big(x(2P)\big)$ divides $4y^2$, and every prime
dividing $\den\big(x(2P)\big)$ divides $2y$.
\end{theorem}

\begin{theorem}[Exact exponent]\label{thm:H}
With $(x,y)$ integral, $y \neq 0$, and $\ell \nmid 6N$ prime,
$v_\ell\big(\den x(2P)\big) = 2\,v_\ell(y)$.
\end{theorem}

At $n=3$ the same picture holds with $\psi_3 = 3x^4+12Nx$ in place of $\psi_2 = 2y$, and the
extraneous primes \emph{move}: for $N=55$, $P=(9,28)$, the prime $7$ divides $\den x(2P)$ but not
$\den x(3P)$, while $13$ and $73$ divide $\den x(3P) = 3^6\cdot 13^2\cdot 73^2$ but not $\den x(2P)$.
Along the doubling tower the behaviour is rigid at odd primes and linear at $2$.

\section{Setup and definitions}

Throughout $N$ is a nonzero integer (occasionally a nonzero element of a field) and
$E_N : y^2 = x^3+N$ is the Weierstrass curve with $a_1=a_2=a_3=a_4=0$, $a_6 = N$.

\begin{definition}[Discriminant and bad primes]
For $E_N$ one has $b_2 = b_4 = b_8 = 0$ and $b_6 = 4N$, hence
\[
  \Delta(E_N) = -b_2^2b_8 - 8b_4^3 - 27b_6^2 + 9b_2b_4b_6 = -432N^2 .
\]
Since $432 = 2^4\cdot 3^3$, the primes dividing $\Delta$ form
$\mathcal B(N) = \{2,3\}\cup\{\ell \text{ prime}: \ell \mid N\}$; equivalently $\ell \in \mathcal B(N)$
iff $\ell \mid 6N$.
\end{definition}

\begin{definition}[Nonsingularity]\label{def:nonsing}
Over a field $F$ with $2\ne 0$, $3 \ne 0$ and $N \ne 0$, every point $(x,y)$ with $y^2 = x^3+N$ is
nonsingular: the partials of $y^2-x^3-N$ are $-3x^2$ and $2y$, which vanish simultaneously only if
$x = y = 0$, forcing $N = 0$.
\end{definition}

\begin{definition}[Denominator and valuation]
For $r\in\QQ$, $\den(r)$ is the positive denominator in lowest terms and $v_\ell(r)$ the $\ell$-adic
valuation. One has $v_\ell(r)<0 \iff \ell \mid \den(r)$, and then $v_\ell(r) = -v_\ell(\den r)$.
\end{definition}

\begin{definition}[Duplication value]
For $x\in\QQ$ with $x^3+N \ne 0$, put $\dbl_N(x) = \dfrac{x^4-8Nx}{4(x^3+N)}$.
\end{definition}

\begin{definition}[Division polynomials]
For $E_N$,
\[
  \psi_1 = 1,\quad \psi_2 = 2y,\quad \psi_3 = 3x^4+12Nx,\quad
  \psi_2\psi_4 = 8y^2\big(x^6+20Nx^3-8N^2\big).
\]
\end{definition}

\begin{definition}[Triplication value]
For $x,y\in\QQ$ with $\psi_3 = 3x^4+12Nx \ne 0$,
\[
  \tri_N(x,y) = \frac{x\,\psi_3^2 - 8y^2(x^6+20Nx^3-8N^2)}{\psi_3^2} = x - \frac{\psi_2\psi_4}{\psi_3^2}.
\]
\end{definition}

\begin{definition}[Doubling tower]
$\dbl_N^0(x) = x$ and $\dbl_N^{k+1}(x) = \dbl_N\big(\dbl_N^k(x)\big)$.
\end{definition}

\begin{proposition}[Duplication bridge]\label{prop:dbl}
Let $P=(x,y)$ be a rational point of $E_N$ with $y \ne 0$. Then the chord--tangent group law gives
$x(P+P) = \dbl_N(x)$.
\end{proposition}

\begin{proof}[Proof sketch]
The tangent slope at $P$ is $\lambda = 3x^2/(2y)$ (here $y \ne 0$ is used), so
$x(2P) = \lambda^2-2x = (9x^4-8xy^2)/(4y^2)$. Substituting $y^2 = x^3+N$ and simplifying
$9x^4-8x(x^3+N) = x^4-8Nx$ gives the claim.
\end{proof}

\begin{proposition}[Triplication bridge]\label{prop:tri}
Let $P=(x,y)$ be a rational point of $E_N$ with $y \ne 0$ and $\psi_3(P) \ne 0$. Then
$2P \neq \pm P$ and $x(3P) = \tri_N(x,y)$.
\end{proposition}

\begin{proof}[Proof sketch]
A direct computation from Proposition \ref{prop:dbl} gives
$x - x(2P) = \psi_3/(4y^2) = \psi_3/\psi_2^2$, so $\psi_3(P)\neq 0$ guarantees $x(2P) \ne x(P)$ and
$P+2P$ is computed by the secant through $P$ and $2P$. Evaluating $\lambda^2 - x - x(2P)$ with
$\lambda = (y(2P)-y)/(x(2P)-x)$ and clearing denominators yields $x - \psi_2\psi_4/\psi_3^2$.
\end{proof}

\section{The mechanism at $n=2$}

Substituting the curve equation, the duplication formula reads $x(2P) = (x^4-8Nx)/(4y^2)$: a quotient
of integers whose denominator, before cancellation, is $4y^2$. Whether a prime survives cancellation
is a question about the numerator.

\begin{lemma}[Numerator nonvanishing]\label{lem:num}
Let $(x,y)\in\ZZ^2$ with $y^2=x^3+N$, and let $\ell$ be a prime with $\ell \nmid 6N$ and $\ell \mid y$.
Then $\ell \nmid x^4-8Nx$.
\end{lemma}

\begin{proof}
Suppose $\ell \mid x^4-8Nx = x(x^3-8N)$. From $\ell \mid y$ and $y^2 = x^3+N$ we get
$x^3 \equiv -N \pmod \ell$. If $\ell \mid x$ then $N \equiv -x^3 \equiv 0$, contradicting
$\ell \nmid N$. Hence $\ell \mid x^3-8N \equiv -9N$, so $\ell \mid 3$ or $\ell \mid N$, contradicting
$\ell \nmid 6N$.
\end{proof}

\begin{theorem}[Mechanism theorem; Theorem \ref{thm:B}]\label{thm:mech2}
Let $(x,y)\in\ZZ^2$ with $y^2=x^3+N$, $y \ne 0$, and let $\ell$ be a prime with $\ell \nmid 6N$. Then
\[
  \ell \mid \den\big(\dbl_N(x)\big) \iff \ell \mid y .
\]
\end{theorem}

\begin{proof}
Write $\dbl_N(x) = A/B$ with $A = x^4-8Nx$ and $B = 4(x^3+N) = 4y^2 \ne 0$.

$(\Leftarrow)$ If $\ell \mid y$ then $\ell \mid B$, and $\ell \nmid A$ by Lemma \ref{lem:num}. In
general, from $A\cdot\den(A/B) = \num(A/B)\cdot B$ and $\ell \mid B$ we get
$\ell \mid A\cdot \den(A/B)$, hence $\ell \mid \den(A/B)$.

$(\Rightarrow)$ The reduced denominator divides $B = 4y^2$. So $\ell \mid 4y^2$; since
$\ell \nmid 6N$ we have $\ell \ne 2$, hence $\ell \mid y$.
\end{proof}

\begin{theorem}[Repaired conjecture; Theorem \ref{thm:G}]\label{thm:rep}
For any integral point $(x,y)$ of $E_N$, $\den(\dbl_N(x))$ divides $4y^2$, and every prime dividing
$\den(\dbl_N(x))$ divides $2y$.
\end{theorem}

\begin{proof}
The reduced denominator of $A/B$ divides $B = 4(x^3+N) = 4y^2$. If $\ell \mid 4y^2$ then either
$\ell \mid 4$, so $\ell = 2 \mid 2y$, or $\ell \mid y^2$, so $\ell \mid y \mid 2y$.
\end{proof}

\begin{theorem}[Exact exponent; Theorem \ref{thm:H}]\label{thm:exp2}
With $(x,y)$ integral on $E_N$, $y \ne 0$, and $\ell \nmid 6N$ prime,
$v_\ell\big(\den \dbl_N(x)\big) = 2 v_\ell(y)$.
\end{theorem}

\begin{proof}[Proof sketch]
If $\ell \nmid y$ both sides vanish by Theorem \ref{thm:mech2}. If $\ell \mid y$, Lemma \ref{lem:num}
gives $v_\ell(A) = 0$, while $v_\ell(B) = v_\ell(4y^2) = 2v_\ell(y)$ since $\ell \nmid 4$. Hence
$v_\ell(A/B) = -2v_\ell(y) < 0$.
\end{proof}

\subsection{The reduction-theoretic reading}

\begin{theorem}[Reduction/torsion bridge; Theorem \ref{thm:C}]\label{thm:red2}
Let $(x,y)$ be integral on $E_N$ with $y \ne 0$, let $\ell \nmid 6N$ be prime, and let
$\bar P = (\bar x,\bar y) \in E_N(\FF_\ell)$ be its reduction. Then
$\ell \mid \den\big(\dbl_N(x)\big) \iff \bar P + \bar P = O$.
\end{theorem}

\begin{proof}
Since $\ell \nmid 6N$, over $\FF_\ell$ we have $2 \ne 0$, $3\ne0$, $\bar N \ne 0$, so $\bar P$ is a
nonsingular point of the reduced curve (Definition \ref{def:nonsing}). Negation is
$(\bar x,\bar y)\mapsto(\bar x,-\bar y)$, so $2\bar P = O$ iff $\bar y = -\bar y$ iff $\bar y = 0$
(as $2 \neq 0$), i.e. iff $\ell \mid y$. Apply Theorem \ref{thm:mech2}.
\end{proof}

\begin{remark}
This is the conceptual heart of the matter: the denominator of $x(2P)$ detects exactly the primes at
which $P$ reduces into the $2$-torsion, equivalently at which $2P$ lies in the kernel of reduction
(the formal group at $\ell$). Bad reduction is irrelevant to that condition. Bad primes are where the
\emph{curve} misbehaves; denominator primes are where the \emph{point} is torsion.
\end{remark}

\section{The counterexamples}

\begin{theorem}[Theorem \ref{thm:A}]\label{thm:c55}
Let $N=55=5\cdot11$ and $P=(9,28)$, so $28^2 = 784 = 9^3+55$. Then
\[
  x(2P) = \frac{6561-3960}{3136} = \frac{2601}{3136}, \qquad 3136 = 2^6\cdot 7^2,
\]
and $7 \nmid \Delta = -1306800$ (indeed $-1306800 \equiv 2 \bmod 7$). Thus the good prime $7$ divides
the denominator and $7 \notin\{2,3,5,11\}$.
\end{theorem}

The fraction is genuinely reduced, since $2601 = 3^2\cdot17^2$ is odd and prime to $7$. Consistently
with Theorem \ref{thm:exp2}, $y = 28 = 2^2\cdot 7$ has $v_7(y)=1$ and the $7$-exponent of the
denominator is $2$.

\begin{theorem}[A twin-prime counterexample]\label{thm:c899}
Let $N = 899 = 29\cdot 31$ and $P = (1,30)$. Then $x(2P) = -799/400$ with $400 = 2^4\cdot 5^2$, and
$5$ is a prime of good reduction with $5 \notin\{2,3,29,31\}$.
\end{theorem}

This example is manufactured, not found: $25m^2-1 = (5m-1)(5m+1)$ gives a semiprime with the free
integral point $(1,5m)$ and guarantees $5 \mid y$ while $5 \nmid 6N$; take $m=6$.

\begin{theorem}[Theorem \ref{thm:F}]\label{thm:inf}
Let $\mathcal F = \{N \in \ZZ : \exists (x,y)\in\ZZ^2,\ y^2 = x^3+N,\ \exists \ell \text{ prime},\
\ell \nmid 6N,\ \ell \mid \den \dbl_N(x)\}$. Then $\mathcal F$ is infinite; it contains $25m^2-1$ for
all $m \ge 1$.
\end{theorem}

\begin{proof}
For $N=25m^2-1$ and $P=(1,5m)$ we have $y^2 = 25m^2 = 1+N$. If $5 \mid 6N = 6(25m^2-1)$ then
$5 \mid 6$, absurd; so $5 \nmid 6N$. Since $5 \mid y \ne 0$, Theorem \ref{thm:mech2} applies. The map
$m \mapsto 25m^2-1$ is injective for $m \ge 1$.
\end{proof}

\begin{theorem}[Theorem \ref{thm:D}]\label{thm:univ2}
Let $\ell \ge 5$ be prime and $m \ge 1$. Put $N = \ell^2m^2-1$, $P = (1,\ell m)$. Then $\ell \nmid 6N$
and $\ell \mid \den \dbl_N(1)$.
\end{theorem}

\begin{proof}
$(\ell m)^2 = 1+N$ puts $P$ on $E_N$. If $\ell \mid 6(\ell^2m^2-1)$ then, since
$\ell \mid 6\ell^2m^2$, we get $\ell \mid 6$, impossible for $\ell \ge 5$. As $\ell \mid y = \ell m
\ne 0$, apply Theorem \ref{thm:mech2}.
\end{proof}

\begin{theorem}[Theorem \ref{thm:E}]\label{thm:many}
Let $S$ be a finite set of primes $\ge 5$, $K = \prod_{\ell\in S}\ell$, $m \ge 1$, $N = K^2m^2-1$,
$P = (1,Km)$. Then for every $\ell \in S$: $\ell \nmid 6N$ and $\ell \mid \den\dbl_N(1)$.
\end{theorem}

\begin{proof}
As in Theorem \ref{thm:univ2}, using $\ell \mid K$: if $\ell \mid 6(K^2m^2-1)$ then $\ell \mid 6$,
impossible; and $\ell \mid K \mid y = Km$.
\end{proof}

For $S=\{5,7,11,13\}$, $K = 5005$, $m=1$: $N = 25050024$ and
$\den x(2P) = 2^2\cdot5^2\cdot7^2\cdot11^2\cdot13^2$, four extraneous primes at once.

\section{The mechanism at $n=3$}

\begin{lemma}[Numerator nonvanishing at $n=3$]\label{lem:num3}
Let $(x,y)$ be integral on $E_N$ and $\ell \nmid 6N$ a prime with $\ell \mid \psi_3(P)$. Then
$\ell \nmid \psi_2\psi_4(P) = 8y^2(x^6+20Nx^3-8N^2)$.
\end{lemma}

\begin{proof}[Proof sketch]
Over $\FF_\ell$ the reduced curve is nonsingular. By Theorem \ref{thm:psi3} below, $\ell\mid\psi_3(P)$
says $\bar P$ has order dividing $3$; since $\bar P \ne O$, it has exact order $3$, hence is neither
$2$- nor $4$-torsion, so $\psi_2(\bar P) = 2\bar y \ne 0$ and $\psi_4(\bar P) \ne 0$. Equivalently,
a resultant identity expresses a power of $2^63^3N^3$ as a polynomial combination of $\psi_3$ and
$x^6+20Nx^3-8N^2$, so simultaneous vanishing forces $\ell \mid 6N$.
\end{proof}

\begin{theorem}[Mechanism theorem at $n=3$]\label{thm:mech3}
Let $(x,y)$ be integral on $E_N$ with $\psi_3(P) = 3x^4+12Nx \ne 0$, and let $\ell \nmid 6N$ be prime.
Then
\[
  \ell \mid \den\big(\tri_N(x,y)\big) \iff \ell \mid x^4+4Nx,
\]
equivalently iff $\ell \mid \psi_3(P)$ (the conditions agree since $\ell \nmid 3$).
\end{theorem}

\begin{proof}[Proof sketch]
Write $\tri_N(x,y) = A/\psi_3^2$ with $A = x\psi_3^2 - \psi_2\psi_4$. If $\ell \mid \psi_3$ then
Lemma \ref{lem:num3} gives $\ell \nmid A$, so $\ell$ survives into the reduced denominator, whose
$\ell$-exponent is $2v_\ell(\psi_3)$. Conversely the reduced denominator divides $\psi_3^2$.
\end{proof}

\begin{theorem}[$\psi_3$ cuts out the $3$-torsion]\label{thm:psi3}
Let $F$ be a field with $2 \ne 0$, $3 \ne 0$, let $N \in F^\times$, and let $P=(X,Y)$ be a point of
$E_N(F)$. Then $3P = O \iff X^4+4NX = 0$.
\end{theorem}

\begin{proof}[Proof sketch]
If $Y=0$ then $P$ is $2$-torsion, so $3P = P \ne O$; and $X^3 = -N$ with $X \ne 0$ gives
$X^4+4NX = X(X^3+4N) = 3NX \ne 0$. If $Y \ne 0$, the identity $X - x(2P) = \psi_3/(4Y^2)$ shows
$x(2P) = X$ exactly when $\psi_3 = 3(X^4+4NX) = 0$; and $3P = O$ iff $2P = -P$, which for affine
points holds iff $x(2P) = X$, the $y$-coordinate condition following automatically on this curve.
\end{proof}

\begin{theorem}[Reduction/torsion bridge at $n=3$]\label{thm:red3}
Let $(x,y)$ be integral on $E_N$ with $\psi_3(P) \ne 0$, let $\ell \nmid 6N$ be prime with reduction
$\bar P \in E_N(\FF_\ell)$. Then
$\ell \mid \den\big(\tri_N(x,y)\big) \iff \bar P + \bar P + \bar P = O$.
\end{theorem}

\begin{proof}
Combine Theorems \ref{thm:mech3} and \ref{thm:psi3} over $F = \FF_\ell$, noting $\ell \mid x^4+4Nx$
iff $\bar x^4 + 4\bar N\bar x = 0$.
\end{proof}

\subsection{The extraneous primes move with $n$}

\begin{theorem}[Counterexample at $n=3$, and the shift]\label{thm:tri55}
For $N = 55$ and $P = (9,28)$,
\[
  x(3P) = -\frac{2302089191}{656538129}, \qquad 656538129 = 3^6\cdot 13^2\cdot 73^2 .
\]
Both $13$ and $73$ are primes of good reduction outside $\{2,3,5,11\}$, so the conjecture fails at
$n=3$ as well. Moreover the extraneous primes at levels $2$ and $3$ are disjoint here:
$7 \mid \den x(2P)$ but $7 \nmid \den x(3P)$, while $13,73 \mid \den x(3P)$ but
$13,73 \nmid \den x(2P)$.
\end{theorem}

Indeed $\psi_3(P) = 3\cdot9^4+12\cdot55\cdot9 = 25623 = 3^3\cdot13\cdot73$ and
$\den x(3P) = \psi_3(P)^2$ exactly: the denominator reads off the division polynomial value at $P$.

\begin{theorem}[No prime is excluded at $n=3$]\label{thm:univ3}
For every prime $\ell \ge 5$, take $N = 1-\ell^3$ and the integral point $P = (\ell,1)$ of $E_N$.
Then $\ell \nmid 6N$ and $\ell \mid \den x(3P)$.
\end{theorem}

\begin{proof}
$1^2 = \ell^3+(1-\ell^3)$ puts $P$ on the curve. If $\ell \mid 6(1-\ell^3)$ then $\ell \mid 6$,
impossible. Also $\psi_3(P) = 3\ell^4+12(1-\ell^3)\ell = \ell(12-9\ell^3) \ne 0$ for $\ell \ge 5$, and
$x^4+4Nx = \ell(\ell^3+4-4\ell^3)$ is divisible by $\ell$. Apply Theorem \ref{thm:mech3}.
\end{proof}

\section{The doubling tower: rigidity versus growth}

\begin{theorem}[Persistence at odd primes]\label{thm:pers}
Let $\ell \ne 2$ be prime, $N \ne 0$ an integer, and $x \in \QQ$ with $v_\ell(x)<0$. Then
$\dbl_N(x) \ne 0$ and $v_\ell\big(\dbl_N(x)\big) = v_\ell(x)$.
\end{theorem}

\begin{proof}
Let $v = v_\ell(x)<0$. As $N \in \ZZ$ and $v_\ell(8)=0$, we have $v_\ell(8N)\ge0$, so
$v_\ell(x^4-8Nx) = \min\{4v,\ v+v_\ell(8N)\} = 4v$, the minimum being attained once. Likewise
$v_\ell(4(x^3+N)) = 0 + \min\{3v, v_\ell(N)\} = 3v$. Hence $v_\ell(\dbl_N(x)) = 4v-3v = v$, finite,
so the value is nonzero.
\end{proof}

\begin{corollary}[Rigidity along the tower]\label{cor:rigid}
For $\ell \ne 2$ prime, $N \ne 0$, and $x$ with $\ell \mid \den(x)$: for every $k \ge 0$,
$\dbl_N^k(x) \ne 0$, $\ell \mid \den(\dbl_N^k(x))$, and
$v_\ell\big(\den \dbl_N^k(x)\big) = v_\ell\big(\den(x)\big)$.
\end{corollary}

\begin{proof}
Induction on $k$ using Theorem \ref{thm:pers}, plus $v_\ell(r) = -v_\ell(\den r)$ when $v_\ell(r)<0$.
\end{proof}

\begin{theorem}[Permanence of extraneous primes]\label{thm:perm}
Let $(x,y)$ be integral on $E_N$ with $N \ne 0$, $y \ne 0$, and let $\ell \nmid 6N$ be a prime with
$\ell \mid y$. Then for every $k \ge 0$,
\[
  \ell \mid \den\big(x(2^{k+1}P)\big), \qquad
  v_\ell\big(\den x(2^{k+1}P)\big) = v_\ell\big(\den x(2P)\big) = 2v_\ell(y).
\]
\end{theorem}

\begin{proof}
By Theorems \ref{thm:mech2} and \ref{thm:exp2}, $\ell \mid \den x(2P)$ with exponent $2v_\ell(y)$.
Since $\ell \nmid 6N$ forces $\ell \ne 2$, Corollary \ref{cor:rigid} applied to $x(2P)$ freezes the
exponent at all further levels.
\end{proof}

\begin{theorem}[Dichotomy at the bad prime $2$]\label{thm:dich}
Let $N \ne 0$ and $x \in \QQ$ with $v_2(x)<0$. Then $\dbl_N(x) \ne 0$ and
$v_2\big(\dbl_N(x)\big) = v_2(x) - 2$. Consequently, if $2 \mid \den(x)$ then for all $k$,
$v_2\big(\den \dbl_N^k(x)\big) = v_2\big(\den(x)\big) + 2k$.
\end{theorem}

\begin{proof}
With $v = v_2(x)<0$: $v_2(x^4-8Nx) = 4v$ since $v_2(8N)\ge 3$, whereas $v_2(4(x^3+N)) = 2+3v$.
Subtracting gives $4v - (2+3v) = v-2$. Iterate.
\end{proof}

\begin{theorem}[Level four for $N=55$]\label{thm:lvl4}
For $N=55$, $P=(9,28)$,
\[
  x(4P) = -\frac{35249882584054239}{21498536380459264},\qquad
  21498536380459264 = 2^8\cdot 7^2\cdot 827^2\cdot 1583^2 .
\]
Here $827$ and $1583$ are primes, and none of $7, 827, 1583$ divides $\Delta = -432\cdot 55^2$. The
exponent of $7$ is $2$ at level $2$ and at level $4$ --- frozen, per Theorem \ref{thm:perm} --- while
the exponent of $2$ grows from $6$ to $8$, exactly $+2$, per Theorem \ref{thm:dich}.
\end{theorem}

In particular the tower form of the conjecture (every prime dividing $\den x(2^kP)$ lies in
$\{2,3,p,q\}$) is false, witnessed at $k=2$ by $\ell = 827$.

\begin{center}
\begin{tabular}{lccc}
\toprule
level & denominator & $v_7$ & $v_2$ \\
\midrule
$x(2P)$ & $2^6\cdot 7^2$ & $2$ & $6$ \\
$x(4P)$ & $2^8\cdot 7^2\cdot 827^2\cdot 1583^2$ & $2$ & $8$ \\
\bottomrule
\end{tabular}
\end{center}

\section{Algorithms}

\begin{algorithmbox}[Denominator spectrum of a multiple]
Given $N$, an integral point $P$ and $n$, compute $nP$ by double-and-add in $E_N(\QQ)$ with exact
rational arithmetic, extract $\den x(nP)$, factor it, and classify each prime as bad ($\ell \mid 6N$)
or extraneous ($\ell \nmid 6N$). Cost: $O(\log n)$ group operations; coordinate bit-size grows like
$\Theta(n^2)$ by the theory of canonical heights, and factoring the denominator dominates.
\end{algorithmbox}

\begin{algorithmbox}[Mechanism verification]
Given $N$ and an integral point $(x,y)$ with $y \ne 0$, compute $D = \den \dbl_N(x)$ and, for each
prime $\ell < B$ with $\ell \nmid 6N$, test $\ell \mid D \iff \ell \mid y$ and the exponent identity
$v_\ell(D) = 2v_\ell(y)$. Cost: $O(B/\log B)$ divisibility tests. This checks
Theorems \ref{thm:mech2} and \ref{thm:exp2} empirically.
\end{algorithmbox}

\begin{algorithmbox}[Extraneous-prime constructor]
Given a finite set $S$ of primes $\ge 5$ and $m \ge 1$, output $K = \prod_{\ell \in S}\ell$,
$N = K^2m^2-1$, $P = (1,Km)$. By Theorem \ref{thm:many} every $\ell \in S$ is a good prime dividing
$\den x(2P)$, with $\ell$-exponent $2$. Deterministic, $O(|S|)$ multiplications, no search.
\end{algorithmbox}

\section{A survey over semiprimes: no factoring signal}

To test whether denominators can be \emph{used}, we surveyed semiprimes $N=pq$ with small factors,
taking every integral point $(x,y)$ with $|x|\le 200$, $y>0$, and collecting all primes occurring in
the denominators of $x(2P)$ and $x(3P)$. Of eleven semiprimes tried, eight possess such a point.
Among those eight: the ``only bad primes'' property held for none ($0\%$); every one exhibited at
least one extraneous good prime ($100\%$); the smaller factor $p$ appeared in $2$ of $8$ cases
($25\%$); the larger factor $q$ appeared in none ($0\%$). For instance $N=15=3\cdot5$ produces
$\{2,3,61,109,569,1295089\}$ and $N = 91 = 7\cdot13$ produces $\{2,3,337\}$ --- an extraneous prime
larger than $N$ itself, with no factor of $N$ in sight.

The interpretation follows from Theorems \ref{thm:mech2} and \ref{thm:mech3}: up to primes dividing
$6N$, $\den x(nP)$ is the square of the division polynomial value $\psi_n(P)$, determined by $N$ and
by the point. Factoring it is as hard as factoring an arbitrary integer of the same size, and it
exhibits $p$ or $q$ only by coincidence.

\section{Discussion}

\subsection{Why the conjecture was plausible, and why it fails}

The intuition behind ``only bad primes'' conflates two notions of degeneracy. Bad primes are where the
\emph{curve} degenerates; denominator primes are where the \emph{point} falls into the kernel of
reduction. A perfectly good curve over $\FF_\ell$ has a finite group of points, and any given rational
point reduces into some torsion class; when that class is killed by $n$, the multiple $nP$ lands in
the formal group and $\ell$ enters the denominator. Theorems \ref{thm:univ2}--\ref{thm:many} show one
can force any prescribed set of good primes to do exactly this.

\subsection{The sharp shape of the truth}

At $n=2$ the results assemble into
\[
  \den\big(x(2P)\big) = 2^{e}\cdot\prod_{\ell \nmid 6N}\ell^{\,2v_\ell(y)}\cdot(\text{a } 3\text{- and }
  N\text{-part}),
\]
in which the good-reduction part is exactly the square of the prime-to-$6N$ part of $y$, and which,
along the doubling tower, is invariant while the $2$-part gains $2$ at each step. In elliptic
divisibility sequence language: $\den x(nP)$ is, up to primes dividing $6N$, the square of
$\psi_n(P)$, so ``which primes appear'' is a question about the zero set of the sequence modulo
$\ell$, not about the discriminant.

\subsection{Relation to elliptic curve factorisation}

Lenstra's method exploits an asymmetry between the prime factors of $N$ by working with a curve
\emph{modulo $N$} and detecting a failed inversion via a gcd; the information comes from the differing
group orders $\#E(\FF_p)$ and $\#E(\FF_q)$, and one searches over curves for a smooth order. The
denominators of rational multiples on a single Mordell curve contain no such asymmetry: by
Theorem \ref{thm:mech2} they see exactly the primes where $\bar P$ is $2$-torsion, and $p \mid N$ has
no privileged role --- indeed such $\ell$ are excluded from the clean statement, since then
$\ell \mid 6N$.

\subsection{Limitations}

The mechanism theorems assume $\ell \nmid 6N$; behaviour at $\ell \in \{2,3\}$ or $\ell \mid N$ needs
separate analysis (we treat $\ell = 2$ along the tower, where the behaviour is genuinely different).
We prove the division-polynomial mechanism for $n=2$, $n=3$ and the tower $n=2^k$; the general-$n$
statement is formulated as Conjecture \ref{conj:eds} below.

\section{Future directions}

\begin{conjecture}[Elliptic-divisibility rigidity for general $n$]\label{conj:eds}
For an integral point $P$ on $E_N$ and a prime $\ell \nmid 6N$, and for every $n \ge 1$:
$\ell \mid \den x(nP)$ if and only if $\ell \mid \psi_n(P)$; moreover $\den x(nP)$ equals
$\psi_n(P)^2$ up to primes dividing $6N$.
\end{conjecture}

The cases $n=2$ ($\psi_2 = 2y$) and $n=3$ ($\psi_3 = 3x^4+12Nx$) are Theorems \ref{thm:mech2} and
\ref{thm:mech3}, each with its reduction-theoretic counterpart. The key insight is that the
elliptic divisibility sequence $W_n = \psi_n(P)$ is precisely the denominator bookkeeping of the
formal group. Falsifiable form: exhibit $N$, $P$, $n$, $\ell \nmid 6N$ with $\ell \mid \den x(nP)$ but
$\ell \nmid \psi_n(P)$.

\medskip\noindent
\textbf{Density of extraneous primes.} Fix $N$ and a non-torsion integral point $P$: for which primes
$\ell$ does $\bar P$ reduce into the $n$-torsion for some $n \le X$? Proving positive density for the
set of extraneous primes occurring in some denominator is the quantitative sequel to
Theorems \ref{thm:univ2}--\ref{thm:many}.

\medskip\noindent
\textbf{Exact exponents at $3$ and at $\ell \mid N$.} We control good primes (exponent $2v_\ell(y)$,
frozen) and $2$ (linear growth). The cases $\ell = 3$ and $\ell \mid N$ should admit a similar
dichotomy according to the reduction type (multiplicative versus additive) at $\ell$.

\medskip\noindent
\textbf{Uniform bounds for fixed $N$.} Theorem \ref{thm:many} makes the number of extraneous primes
unbounded, but with $N$ growing. For fixed $N$, Theorem \ref{thm:rep} bounds the count by
$\omega(2y)$, turning the question into one about factorisations of $y$-coordinates of integral
points.

\medskip\noindent
\textbf{Other multiplication towers.} The dichotomy (frozen at odd good primes, $+2$ at $2$) reflects
the factor $4$ in the duplication denominator; for the tripling tower the analogous factor is $9$,
suggesting that $3$ should grow linearly while all other good primes freeze.

\section{Conclusion}

The ``only bad primes'' conjecture for Mordell curves is false, for a reason both simple and
structural. The primes appearing in $\den x(nP)$ are the primes at which $P$ reduces into the
$n$-torsion of a perfectly good reduction; they are read off from the value of the $n$-th division
polynomial at $P$ and have nothing to do with the discriminant beyond a bounded contribution from
$2$, $3$ and the divisors of $N$. Concretely: $N=55$, $P=(9,28)$, $x(2P) = 2601/3136$, and the good
prime $7$ sits in the denominator. Everything else follows: the failure is universal, the exponents
are exactly $2v_\ell(y)$, the failure is permanent along the doubling tower with frozen exponents at
odd primes and $+2$ per level at $2$, and the correct statement --- every prime dividing
$\den x(2P)$ divides $2y$ --- is about the point, not the curve.

